ePassword() {        $('.form-control').css("border", "1px solid #cccccc");        $('div.herr').text('');        var frmBasicOldPwd		= $("#frmBasicOldPwd").val();        var frmBasicNewPwd			= $("#frmBasicNewPwd").val();        var frmBasicConfirmPwd		= $("#frmBasicConfirmPwd").val();        if(jsTrim(frmBasicOldPwd)== ""){            $('#ErrfrmBasicOldPwd').text("Please fill the old Password");            $('#frmBasicOldPwd').focus();            $('#frmBasicOldPwd').css("border", "1px solid #B94A48");            return false;        }        /*else if(jsTrim(frmBasicOldPwd).length<=5) {            $('#ErrfrmBasicOldPwd').text("Invalid Password!");            $('#frmBasicOldPwd').focus();            $('#frmBasicOldPwd').css("border", "1px solid #B94A48");            return false;        }*/        if(jsTrim(frmBasicNewPwd)== ""){            $('#ErrfrmBasicNewPwd').text("Please fill the New Password");            $('#frmBasicNewPwd').focus();            $('#frmBasicNewPwd').css("border", "1px solid #B94A48");            return false;        }        /*else if(!isPasswordRule(frmBasicNewPwd)) {            $('#ErrfrmBasicNewPwd').text("Invalid Password!");            $('#frmBasicNewPwd').focus();            $('#frmBasicNewPwd').css("border", "1px solid #B94A48");            return false;        }*/        if(jsTrim(frmBasicConfirmPwd)== ""){            $('#ErrfrmBasicConfirmPwd').text("Please fill the confirm Password");            $('#frmBasicConfirmPwd').focus();            $('#frmBasicConfirmPwd').css("border", "1px solid #B94A48");            return false;        }        if(jsTrim(frmBasicNewPwd)!=jsTrim(frmBasicConfirmPwd)){            $('#ErrfrmBasicConfirmPwd').text("Password and Confirm Password should be same");            $('#frmBasicConfirmPwd').focus();            $('#frmBasicConfirmPwd').css("border", "1px solid #B94A48");            return false;        }        var Parameters = "rfrom=1&op="+encodeURIComponent(frmBasicOldPwd)+"&np="+encodeURIComponent(frmBasicNewPwd)+"&cp="+encodeURIComponent(frmBasicConfirmPwd);        MakeAsynPostRequest(base_path+'profile/updatePassword',Parameters,'json',fnChangePasswordRes);        return false;    }    function fnChangePasswordRes(data) {        if(data!='') {            if(data.errcode == '404') {                fnCallSessionExpire();                return false;            } else if(data.errcode==='-1') {                $('#ErrOldPassword').text(data.msg);                return false;            } else if(data.errcode===1) {                $('#divSuccessBasicInfoMsg').removeClass('hide');                $('#divSuccessBasicInfoMsg').text(data.msg);                fnRedirectPageTimeOut(base_path);            }        }    }</script><?php $this->load->view(CNFCOMPANY . 'template/pagefooter'); ?>